-- PostgreSQL: one atomic statement. Requires an existing users.id = 1.
-- Design: 33% midnight sidebar, 67% white main column, warm gold accents, 11px body.
-- All profile details, organizations, and accomplishments are fictional.
-- Each execution creates a new resume; IDs are generated by the database.
WITH
content AS (
    SELECT $resume_data$
[
{"label": "Contact", "type": "contact", "columnPosition": 0, "showHeading": true, "subsections": [{"label": "Contact details", "fields": [{"label": "Location", "value": [{"type": "paragraph", "label": "Location", "children": [{"text": "Austin, TX", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Email", "value": [{"type": "paragraph", "label": "Email", "children": [{"text": "john.doe@example.com", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Phone", "value": [{"type": "paragraph", "label": "Phone", "children": [{"text": "(512) 555-0176", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Website", "value": [{"type": "paragraph", "label": "Website", "children": [{"text": "johndoe.example.com", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}]}]},
{"label": "Expertise", "type": "skills", "columnPosition": 0, "showHeading": true, "subsections": [{"label": "Core strengths", "fields": [{"label": "Operations", "value": [{"type": "paragraph", "label": "Operations", "children": [{"text": "Process improvement", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Delivery", "value": [{"type": "paragraph", "label": "Delivery", "children": [{"text": "Program delivery", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Planning", "value": [{"type": "paragraph", "label": "Planning", "children": [{"text": "Capacity planning", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Reporting", "value": [{"type": "paragraph", "label": "Reporting", "children": [{"text": "Performance reporting", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Leadership", "value": [{"type": "paragraph", "label": "Leadership", "children": [{"text": "Team leadership", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}]}, {"label": "Tools", "fields": [{"label": "Tools heading", "value": [{"type": "paragraph", "label": "Tools heading", "children": [{"text": "TOOLS", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true, "color": "#E5BE7E"}]}]}, {"label": "Analysis tools", "value": [{"type": "paragraph", "label": "Analysis tools", "children": [{"text": "Excel / SQL / Tableau", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Project tools", "value": [{"type": "paragraph", "label": "Project tools", "children": [{"text": "Asana / Notion", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}]}]},
{"label": "Education", "type": "education", "columnPosition": 0, "showHeading": true, "subsections": [{"label": "Hillcrest University", "fields": [{"label": "Degree", "value": [{"type": "paragraph", "label": "Degree", "children": [{"text": "B.S. Business\nAdministration", "fontSizeOffset": 0, "lineHeightOffset": 0, "bold": true, "color": "#F0F3F6"}]}]}, {"label": "School", "value": [{"type": "paragraph", "label": "School", "children": [{"text": "Hillcrest University", "fontSizeOffset": 0, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}, {"label": "Dates", "value": [{"type": "paragraph", "label": "Dates", "children": [{"text": "2014 - 2018", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#F0F3F6"}]}]}]}]},
{"label": "Header", "type": "header", "columnPosition": 1, "showHeading": false, "subsections": [{"label": "John Doe", "fields": [{"label": "Name", "value": [{"type": "paragraph", "label": "Name", "children": [{"text": "JOHN DOE", "fontSizeOffset": 19, "lineHeightOffset": 0, "bold": true, "color": "#1F2C3A"}]}]}, {"label": "Title", "value": [{"type": "paragraph", "label": "Title", "children": [{"text": "OPERATIONS MANAGER", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true, "color": "#94652B"}]}]}, {"label": "Tagline", "value": [{"type": "paragraph", "label": "Tagline", "children": [{"text": "Clear systems. Strong teams. Better outcomes.", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#657180"}]}]}]}]},
{"label": "Profile", "type": "summary", "columnPosition": 1, "showHeading": true, "subsections": [{"label": "Professional profile", "fields": [{"label": "Summary", "value": [{"type": "paragraph", "label": "Summary", "children": [{"text": "Operations manager with 8 years of experience helping growing teams work better. Builds practical processes, turns data into clear decisions, and leads cross-functional programs from planning to delivery.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]},
{"label": "Experience", "type": "workHistory", "columnPosition": 1, "showHeading": true, "subsections": [{"label": "Harborline Services", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Operations Manager", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Harborline Services | Austin, TX", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#657180"}]}]}, {"label": "Dates", "value": [{"type": "paragraph", "label": "Dates", "children": [{"text": "2022 - Present", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#94652B"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Led a 12-person team supporting 60 business clients; raised on-time delivery from 86% to 97%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Rebuilt intake and scheduling workflows, reducing turnaround time by 28%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Created weekly performance dashboards that saved 6 hours of manual reporting.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}, {"label": "Cedar & Co.", "fields": [{"label": "Job Title", "value": [{"type": "paragraph", "label": "Job Title", "children": [{"text": "Operations Analyst", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Company", "value": [{"type": "paragraph", "label": "Company", "children": [{"text": "Cedar & Co. | Austin, TX", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#657180"}]}]}, {"label": "Dates", "value": [{"type": "paragraph", "label": "Dates", "children": [{"text": "2018 - 2022", "fontSizeOffset": -0.5, "lineHeightOffset": 0, "color": "#94652B"}]}]}, {"label": "Description", "value": [{"type": "unordered-list", "children": [{"type": "list-item", "children": [{"text": "Analyzed service demand and staffing patterns to reduce overtime costs by 16%.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}, {"type": "list-item", "children": [{"text": "Documented 20 core workflows and helped cut new-hire ramp-up time by 3 weeks.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}]},
{"label": "Selected Initiative", "type": "projects", "columnPosition": 1, "showHeading": true, "subsections": [{"label": "Launch Playbook", "fields": [{"label": "Project Title", "value": [{"type": "paragraph", "label": "Project Title", "children": [{"text": "Regional Launch Playbook", "fontSizeOffset": 1, "lineHeightOffset": 0, "bold": true}]}]}, {"label": "Description", "value": [{"type": "paragraph", "label": "Description", "children": [{"text": "Built a shared launch checklist, ownership map, and training kit for 3 new service regions. All locations opened on schedule, with a 22% reduction in first-month support requests.", "fontSizeOffset": 0, "lineHeightOffset": 0}]}]}]}]}
]
$resume_data$::jsonb AS sections
),
new_resume AS (
    INSERT INTO resumes (user_id, title, styling, layout, created_at, updated_at)
    VALUES (
        1,
        'John Doe - Midnight Sidebar',
        '{"display":"flex","fontFamily":"Arial, Helvetica, sans-serif","fontSize":"11.5px","lineHeight":1.4,"color":"#24343D","backgroundColor":"#FFFFFF"}'::json,
        '{"padding":{"top":"2rem","right":"1.8rem","bottom":"2rem","left":"1.5rem"},"gap":{"horizontal":"0.35rem","vertical":"0.5rem","subsection":"0.7rem","field":"0.15rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    )
    RETURNING id, title
),
new_columns AS (
    INSERT INTO columns (resume_id, position, styling, layout, created_at, updated_at)
    SELECT r.id, c.position, '{}'::json, c.layout,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_resume r
    CROSS JOIN (VALUES
        (0, '{"width":{"auto":false,"value":"33%"},"padding":{"top":"0rem","right":"1.1rem","bottom":"0rem","left":"0rem"}}'::json),
        (1, '{"width":{"auto":false,"value":"67%"},"padding":{"top":"0rem","right":"0rem","bottom":"0rem","left":"1.3rem"}}'::json)
    ) AS c(position, layout)
    RETURNING id, position
),
section_data AS (
    SELECT (s.ordinality - 1)::integer AS position, s.item
    FROM content
    CROSS JOIN LATERAL jsonb_array_elements(content.sections)
        WITH ORDINALITY AS s(item, ordinality)
),
new_sections AS (
    INSERT INTO sections (
        column_id, label, type, value, show_heading, position,
        styling, layout, created_at, updated_at
    )
    SELECT c.id, s.item->>'label', s.item->>'type',
        jsonb_build_array(jsonb_build_object(
            'type', 'heading', 'label', s.item->>'label',
            'children', jsonb_build_array(jsonb_build_object(
                'text', upper(s.item->>'label'), 'bold', true,
                'fontSizeOffset', 0, 'lineHeightOffset', 0,
                'color', CASE WHEN c.position = 0 THEN '#E5BE7E' ELSE '#94652B' END
            ))
        ))::json,
        (s.item->>'showHeading')::boolean, s.position,
        CASE WHEN c.position = 0
            THEN '{"backgroundColor":"#1F2C3A","color":"#F0F3F6"}'::json
            ELSE '{}'::json END,
        '{"display":"grid","grid":{"columns":1},"padding":{"top":"0rem","bottom":"0rem"}}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM section_data s
    JOIN new_columns c ON c.position = (s.item->>'columnPosition')::integer
    RETURNING id, position
),
subsection_data AS (
    SELECT s.id AS section_id, (sub.ordinality - 1)::integer AS position, sub.item
    FROM new_sections s
    JOIN section_data d ON d.position = s.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'subsections')
        WITH ORDINALITY AS sub(item, ordinality)
),
new_subsections AS (
    INSERT INTO subsections (
        section_id, label, type, position, styling, layout, created_at, updated_at
    )
    SELECT d.section_id, d.item->>'label', s.item->>'type', d.position,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM subsection_data d
    JOIN new_sections n ON n.id = d.section_id
    JOIN section_data s ON s.position = n.position
    RETURNING id, section_id, position
),
new_fields AS (
    INSERT INTO fields (
        subsection_id, label, value, position, styling, layout, created_at, updated_at
    )
    SELECT sub.id, f.item->>'label', (f.item->'value')::json,
        (f.ordinality - 1)::integer,
        '{"fontSizeOffset":0,"lineHeightOffset":0}'::json, '{}'::json,
        CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
    FROM new_subsections sub
    JOIN subsection_data d ON d.section_id = sub.section_id AND d.position = sub.position
    CROSS JOIN LATERAL jsonb_array_elements(d.item->'fields')
        WITH ORDINALITY AS f(item, ordinality)
    RETURNING id
)
SELECT id AS resume_id, title, (SELECT count(*) FROM new_fields) AS fields_created
FROM new_resume;
